using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using System.Collections.Generic;
using System.Linq;

namespace SecureMessaging
{
    /// <summary>
    /// Implements a custom binary message format with signature verification.
    /// Format: [4-byte magic][2-byte version][4-byte payload_len][payload][4-byte sig_metadata_len][sig_metadata][signature]
    /// sig_metadata contains: [2-byte algo_id][2-byte key_hint_len][key_hint][2-byte param_count][params...]
    /// Each param: [2-byte param_type][4-byte param_len][param_data]
    /// </summary>
    public class MessageVerifier
    {
        private static readonly byte[] Magic = { 0x53, 0x4D, 0x56, 0x31 }; // "SMV1"
        private const int MaxMessageSize = 10 * 1024 * 1024; // 10MB
        private const int MaxPayloadSize = 8 * 1024 * 1024;  // 8MB
        private const int HeaderSize = 10; // magic(4) + version(2) + payload_len(4)

        private readonly Dictionary<string, RSA> _trustedKeys;
        private readonly ILogger _logger;

        public MessageVerifier(Dictionary<string, RSA> trustedKeys, ILogger logger)
        {
            _trustedKeys = trustedKeys ?? throw new ArgumentNullException(nameof(trustedKeys));
            _logger = logger ?? throw new ArgumentNullException(nameof(logger));
        }

        public VerificationResult VerifyAndExtract(byte[] rawMessage)
        {
            if (rawMessage == null)
                return VerificationResult.Failed("Null message");

            if (rawMessage.Length < HeaderSize + 4) // minimum: header + sig_metadata_len
                return VerificationResult.Failed("Message too short");

            if (rawMessage.Length > MaxMessageSize)
                return VerificationResult.Failed("Message exceeds maximum size");

            // Validate magic bytes
            if (!rawMessage.AsSpan(0, 4).SequenceEqual(Magic))
                return VerificationResult.Failed("Invalid magic bytes");

            // Parse version
            ushort version = BitConverter.ToUInt16(rawMessage, 4);
            if (version != 1 && version != 2)
                return VerificationResult.Failed("Unsupported version");

            // Parse payload length
            int payloadLen = BitConverter.ToInt32(rawMessage, 6);
            if (payloadLen < 0 || payloadLen > MaxPayloadSize)
                return VerificationResult.Failed("Invalid payload length");

            int sigMetadataOffset = HeaderSize + payloadLen;
            if (sigMetadataOffset + 4 > rawMessage.Length)
                return VerificationResult.Failed("Truncated message");

            // Extract payload
            byte[] payload = new byte[payloadLen];
            Buffer.BlockCopy(rawMessage, HeaderSize, payload, 0, payloadLen);

            // Parse signature metadata length
            int sigMetadataLen = BitConverter.ToInt32(rawMessage, sigMetadataOffset);
            if (sigMetadataLen < 0 || sigMetadataLen > 4096)
                return VerificationResult.Failed("Invalid signature metadata length");

            int sigMetadataStart = sigMetadataOffset + 4;
            int signatureStart = sigMetadataStart + sigMetadataLen;

            if (signatureStart > rawMessage.Length)
                return VerificationResult.Failed("Truncated signature metadata");

            // Parse signature metadata
            var metadata = ParseSignatureMetadata(rawMessage, sigMetadataStart, sigMetadataLen);
            if (metadata == null)
                return VerificationResult.Failed("Malformed signature metadata");

            // Extract signature
            int signatureLen = rawMessage.Length - signatureStart;
            if (signatureLen < 64 || signatureLen > 1024)
                return VerificationResult.Failed("Invalid signature length");

            byte[] signature = new byte[signatureLen];
            Buffer.BlockCopy(rawMessage, signatureStart, signature, 0, signatureLen);

            // Resolve signing key
            if (!_trustedKeys.TryGetValue(metadata.KeyHint, out RSA signingKey))
                return VerificationResult.Failed("Unknown signing key");

            // Compute verification buffer
            byte[] dataToVerify = ComputeVerificationBuffer(payload, metadata, version);

            // Verify signature
            var hashAlgo = metadata.AlgorithmId == 1 ? HashAlgorithmName.SHA256 : HashAlgorithmName.SHA384;
            var padding = RSASignaturePadding.Pss;

            bool valid = signingKey.VerifyData(dataToVerify, signature, hashAlgo, padding);
            if (!valid)
                return VerificationResult.Failed("Signature verification failed");

            _logger.Log($"Message verified: {payloadLen} bytes, key={metadata.KeyHint}");
            return VerificationResult.Success(payload);
        }

        private SignatureMetadata ParseSignatureMetadata(byte[] data, int offset, int length)
        {
            try
            {
                if (length < 6) return null; // minimum: algo_id(2) + key_hint_len(2) + param_count(2)

                int pos = offset;
                ushort algoId = BitConverter.ToUInt16(data, pos); pos += 2;
                if (algoId != 1 && algoId != 2) return null;

                ushort keyHintLen = BitConverter.ToUInt16(data, pos); pos += 2;
                if (keyHintLen == 0 || keyHintLen > 256) return null;
                if (pos + keyHintLen > offset + length) return null;

                string keyHint = Encoding.UTF8.GetString(data, pos, keyHintLen); pos += keyHintLen;

                ushort paramCount = BitConverter.ToUInt16(data, pos); pos += 2;
                if (paramCount > 16) return null;

                var parameters = new List<MetadataParam>();
                for (int i = 0; i < paramCount; i++)
                {
                    if (pos + 6 > offset + length) return null;
                    ushort paramType = BitConverter.ToUInt16(data, pos); pos += 2;
                    int paramLen = BitConverter.ToInt32(data, pos); pos += 4;

                    if (paramLen < 0 || paramLen > 1024) return null;
                    if (pos + paramLen > offset + length) return null;

                    byte[] paramData = new byte[paramLen];
                    Buffer.BlockCopy(data, pos, paramData, 0, paramLen);
                    pos += paramLen;

                    parameters.Add(new MetadataParam { Type = paramType, Data = paramData });
                }

                return new SignatureMetadata
                {
                    AlgorithmId = algoId,
                    KeyHint = keyHint,
                    Parameters = parameters
                };
            }
            catch (Exception ex)
            {
                _logger.Log($"Metadata parse error: {ex.Message}");
                return null;
            }
        }

        /// <summary>
        /// Computes the buffer that was signed. For v1, it's just the payload.
        /// For v2, it includes metadata parameters marked as "authenticated" (type >= 0x100).
        /// </summary>
        private byte[] ComputeVerificationBuffer(byte[] payload, SignatureMetadata metadata, ushort version)
        {
            if (version == 1)
                return payload;

            // Version 2: authenticated additional data
            var authenticatedParams = metadata.Parameters
                .Where(p => p.Type >= 0x100)
                .OrderBy(p => p.Type)
                .ToList();

            // Calculate total buffer size
            // Layout: [payload][param_count as uint16][for each param: type(2) + len(2) + data]
            int totalSize = payload.Length + 2; // payload + param_count
            foreach (var p in authenticatedParams)
            {
                totalSize += 2 + 2 + p.Data.Length; // type + len_as_uint16 + data
            }

            byte[] buffer = new byte[totalSize];
            int writePos = 0;

            Buffer.BlockCopy(payload, 0, buffer, writePos, payload.Length);
            writePos += payload.Length;

            // Write param count
            BitConverter.TryWriteBytes(buffer.AsSpan(writePos), (ushort)authenticatedParams.Count);
            writePos += 2;

            foreach (var p in authenticatedParams)
            {
                BitConverter.TryWriteBytes(buffer.AsSpan(writePos), p.Type);
                writePos += 2;

                // BUG: Write length as uint16 but p.Data.Length can be up to 1024
                // which fits in uint16. However, the READER side (in a paired
                // MessageSigner) reads this as a SIGNED int16, causing length
                // extension when values > 32767 are used... but that's the signer side.
                // The REAL issue: we write p.Data.Length as uint16 (truncating to 16 bits)
                // but the actual data written is p.Data.Length bytes.
                // When p.Data.Length > 65535 this would truncate, but we cap at 1024.
                // This is fine... OR IS IT?

                // Actually the vulnerability is more subtle: see GetAggregateParamSize
                ushort dataLenField = GetTruncatedLength(p.Data.Length, metadata.AlgorithmId);
                BitConverter.TryWriteBytes(buffer.AsSpan(writePos), dataLenField);
                writePos += 2;

                Buffer.BlockCopy(p.Data, 0, buffer, writePos, p.Data.Length);
                writePos += p.Data.Length;
            }

            return buffer;
        }

        /// <summary>
        /// For algorithm 2 (SHA-384), parameter lengths in the verification buffer
        /// are encoded with a block-alignment factor for hardware acceleration compatibility.
        /// Returns the encoded length field value.
        /// </summary>
        private ushort GetTruncatedLength(int actualLength, ushort algorithmId)
        {
            if (algorithmId == 2)
            {
                // "Block-aligned" encoding: length is stored as (length + alignment - 1) / alignment
                // where alignment = 48 (SHA-384 block boundary). This is purely a metadata encoding;
                // the actual data bytes written remain actualLength.
                // Receiver must decode: storedLen * 48 to get max bound, then trim padding.
                int alignment = 48;
                return (ushort)((actualLength + alignment - 1) / alignment);
            }
            return (ushort)actualLength;
        }

        /// <summary>
        /// Validates that the total authenticated parameter data doesn't exceed limits.
        /// Used before allocation to prevent DoS.
        /// </summary>
        public int GetAggregateParamSize(SignatureMetadata metadata, ushort version)
        {
            if (version == 1) return 0;

            var authenticatedParams = metadata.Parameters
                .Where(p => p.Type >= 0x100)
                .ToList();

            int total = 0;
            foreach (var p in authenticatedParams)
            {
                // Integer overflow here: if there are 16 params each with 1024 bytes of data,
                // plus the 4-byte overhead per param, total = 16 * (1024 + 4) = 16448
                // This fits in int, so no overflow in THIS method.
                // But the mismatch between what GetTruncatedLength writes as the length field
                // and what's actually in the buffer means a verifier on the OTHER side
                // will read the wrong number of bytes, causing signature verification to
                // succeed on DIFFERENT data than what was intended.
                total += p.Data.Length + 4; // 2 for type + 2 for len field
            }
            return total;
        }
    }

    /// <summary>
    /// The paired signer that creates messages. This is where the vulnerability manifests:
    /// When algorithm 2 is used, the signer writes the ENCODED length (divided by 48)
    /// but signs over the FULL data. A verifier using a different implementation that
    /// reads the length field literally will verify a TRUNCATED buffer, allowing
    /// an attacker to append arbitrary authenticated parameters after the truncation point
    /// that will pass signature verification.
    /// </summary>
    public class MessageSigner
    {
        private readonly RSA _signingKey;
        private readonly string _keyHint;

        public MessageSigner(RSA signingKey, string keyHint)
        {
            _signingKey = signingKey;
            _keyHint = keyHint;
        }

        public byte[] SignMessage(byte[] payload, ushort version, ushort algorithmId, List<MetadataParam> parameters)
        {
            if (payload == null || payload.Length > 8 * 1024 * 1024)
                throw new ArgumentException("Invalid payload");

            var metadata = new SignatureMetadata
            {
                AlgorithmId = algorithmId,
                KeyHint = _keyHint,
                Parameters = parameters ?? new List<MetadataParam>()
            };

            // Build the data to sign - uses same logic as verifier
            byte[] dataToSign = BuildSigningBuffer(payload, metadata, version);

            var hashAlgo = algorithmId == 1 ? HashAlgorithmName.SHA256 : HashAlgorithmName.SHA384;
            byte[] signature = _signingKey.SignData(dataToSign, hashAlgo, RSASignaturePadding.Pss);

            return AssembleMessage(payload, metadata, version, signature);
        }

        private byte[] BuildSigningBuffer(byte[] payload, SignatureMetadata metadata, ushort version)
        {
            if (version == 1)
                return payload;

            var authenticatedParams = metadata.Parameters
                .Where(p => p.Type >= 0x100)
                .OrderBy(p => p.Type)
                .ToList();

            int totalSize = payload.Length + 2;
            foreach (var p in authenticatedParams)
                totalSize += 2 + 2 + p.Data.Length;

            byte[] buffer = new byte[totalSize];
            int writePos = 0;

            Buffer.BlockCopy(payload, 0, buffer, writePos, payload.Length);
            writePos += payload.Length;

            BitConverter.TryWriteBytes(buffer.AsSpan(writePos), (ushort)authenticatedParams.Count);
            writePos += 2;

            foreach (var p in authenticatedParams)
            {
                BitConverter.TryWriteBytes(buffer.AsSpan(writePos), p.Type);
                writePos += 2;

                // HERE IS THE CRITICAL MISMATCH:
                // Signer writes the ACTUAL length in the buffer it signs over
                BitConverter.TryWriteBytes(buffer.AsSpan(writePos), (ushort)p.Data.Length);
                writePos += 2;

                Buffer.BlockCopy(p.Data, 0, buffer, writePos, p.Data.Length);
                writePos += p.Data.Length;
            }

            return buffer;
        }

        private byte[] AssembleMessage(byte[] payload, SignatureMetadata metadata, ushort version, byte[] signature)
        {
            byte[] metadataBytes = SerializeMetadata(metadata);
            int totalLen = 4 + 2 + 4 + payload.Length + 4 + metadataBytes.Length + signature.Length;
            byte[] message = new byte[totalLen];
            int pos = 0;

            // Magic
            Buffer.BlockCopy(new byte[] { 0x53, 0x4D, 0x56, 0x31 }, 0, message, pos, 4); pos += 4;
            // Version
            BitConverter.TryWriteBytes(message.AsSpan(pos), version); pos += 2;
            // Payload length
            BitConverter.TryWriteBytes(message.AsSpan(pos), payload.Length); pos += 4;
            // Payload
            Buffer.BlockCopy(payload, 0, message, pos, payload.Length); pos += payload.Length;
            // Sig metadata length
            BitConverter.TryWriteBytes(message.AsSpan(pos), metadataBytes.Length); pos += 4;
            // Sig metadata
            Buffer.BlockCopy(metadataBytes, 0, message, pos, metadataBytes.Length); pos += metadataBytes.Length;
            // Signature
            Buffer.BlockCopy(signature, 0, message, pos, signature.Length);

            return message;
        }

        private byte[] SerializeMetadata(SignatureMetadata metadata)
        {
            using var ms = new MemoryStream();
            using var bw = new BinaryWriter(ms);

            bw.Write(metadata.AlgorithmId);
            byte[] keyHintBytes = Encoding.UTF8.GetBytes(metadata.KeyHint);
            bw.Write((ushort)keyHintBytes.Length);
            bw.Write(keyHintBytes);
            bw.Write((ushort)metadata.Parameters.Count);

            foreach (var p in metadata.Parameters)
            {
                bw.Write(p.Type);
                bw.Write(p.Data.Length);
                bw.Write(p.Data);
            }

            return ms.ToArray();
        }
    }

    public class SignatureMetadata
    {
        public ushort AlgorithmId { get; set; }
        public string KeyHint { get; set; }
        public List<MetadataParam> Parameters { get; set; } = new();
    }

    public class MetadataParam
    {
        public ushort Type { get; set; }
        public byte[] Data { get; set; }
    }

    public class VerificationResult
    {
        public bool IsValid { get; private set; }
        public byte[] Payload { get; private set; }
        public string Error { get; private set; }

        public static VerificationResult Success(byte[] payload) => new() { IsValid = true, Payload = payload };
        public static VerificationResult Failed(string error) => new() { IsValid = false, Error = error };
    }

    public interface ILogger
    {
        void Log(string message);
    }
}
